using System.IO;
using System.Text.Json;
using System.Windows;
using VisionFramework;
using VisionPluginContracts;
using VisionPlugins.CameraMapping;

static class Program {
 static int checks;static void Check(bool value,string message){if(!value)throw new Exception(message);checks++;}
 static JsonElement J<T>(T value)=>JsonSerializer.SerializeToElement(value);
 [STAThread]static int Main(){string output=Path.GetFullPath(Environment.GetEnvironmentVariable("CAMERAMAPPING_RESET_CHECK_OUTPUT")??"analysis/camera-mapping/b3-input-lifecycle-source-20261019/reset-verification");Directory.CreateDirectory(output);try{_ = new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Scenario(output,false,false);Scenario(output,true,false);Scenario(output,false,true);File.WriteAllText(Path.Combine(output,"checks.json"),JsonSerializer.Serialize(new{passed=true,checks,originalDesktop=false,scope="production configuration reset, effective readback, partial apply and scope lifecycle"}));Console.WriteLine($"PASS {checks} camera mapping reset/lifecycle checks");return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
 static void Scenario(string output,bool rejectHomo,bool rejectBinding){
  string key=$"apply-{rejectHomo}-bind-{rejectBinding}";var plugin=new CameraMappingPlugin();using var rootScope=new ModuleExecutionScope();var scope=rootScope.ForProcedure(key);
  var backing=plugin.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());
  var input=new Dictionary<string,PortValue>{["ObjectPointInput1"]=PortValue.Point(new(0,0)),["ObjectPointInput2"]=PortValue.Point(new(10,0)),["TargetPointInput1"]=PortValue.Point(new(10,-5)),["TargetPointInput2"]=PortValue.Point(new(30,-5))};
  Check(plugin.CreateRuntime().ExecuteAsync(new("map",output,input,backing){Scope=scope},default).Result.Status==ModuleStatus.Success,"seed valid cached calibration: "+key);
  string oldPath=Path.Combine(output,key+"-old.iwcal");backing["CalibPathName"]=J(oldPath);backing["RefreshFileEnable"]=J(true);backing["WeightFactor"]=J(35);backing["HomoFreedom"]=J(3);backing["WeightFun"]=J(1);backing["Data3"]=J("Data3#1");backing["Data8"]=J("Data8#1");backing["ConfigurationUserData"]=J(JsonSerializer.Serialize(new Dictionary<string,string>{{"@CalibPathName","True"},{"@RefreshFileEnable","True"},{"@WeightFactor","True"},{"Param.InputWay","1"}}));
  var service=new Subscriptions{Reject=rejectBinding?"RefreshFileEnable":null};service.Seed("CalibPathName","string",Path.Combine(output,"bound.iwcal"));service.Seed("RefreshFileEnable","bool","False");service.Seed("WeightFactor","int","77");var confirmations=new Confirmations();var notifications=new Notifications();var applied=new List<Dictionary<string,JsonElement>>();bool recording=false;int runs=0,atomic=0;
  IReadOnlyDictionary<string,JsonElement> Effective(){var result=new Dictionary<string,JsonElement>(backing);foreach(var item in service.Bindings){var value=(ConfigurationConstantReference)item.Value.Reference;result[item.Key]=value.NativeType switch{"int"=>J(int.Parse(value.Literal)),"bool"=>J(bool.Parse(value.Literal)),_=>J(value.Literal)};}return result;}
  var node=new NodeDocument("map",CameraMappingPlugin.Id,"1","Map",backing);var context=new ToolEditorContext(node,output,next=>{if(recording){applied.Add(next.ToDictionary(p=>p.Key,p=>p.Value.Clone()));if(rejectHomo&&next["HomoFreedom"].GetInt32()==1&&backing["HomoFreedom"].GetInt32()==3)throw new InvalidOperationException("host rejected HomoFreedom");}backing=next;},_=>{runs++;throw new InvalidOperationException("reset must not execute");}){Scope=scope,ReadEffectiveParameters=Effective,ConfigurationSubscriptions=service,ConfigurationConfirmations=confirmations,ConfigurationNotifications=notifications,ResetConfigurationParameters=_=>{atomic++;throw new InvalidOperationException("atomic reset must not be called");}};
  using var session=plugin.CreateConfiguration(context);var state=session.State;foreach(string name in new[]{"CalibPathName","RefreshFileEnable","WeightFactor"}){var n=state.Find(name)!;state.SetProgrammatic(n,"IsSub","True");state.ApplySubscription(n,service.Read(new(ConfigurationSubscriptionDomain.Parameter,name,name=="WeightFactor"?"int":name=="RefreshFileEnable"?"bool":"string")),true);}
  service.Seed("CalibPathName","string",Path.Combine(output,"bound.iwcal"));service.Seed("RefreshFileEnable","bool","False");service.Seed("WeightFactor","int","77");service.Clears.Clear();confirmations.Allow=false;int before=applied.Count;state.Invoke(state.Find("Button_ResetAlgoParams")!);Check(service.Clears.Count==0&&applied.Count==before,"declined reset performs no clear or write: "+key);
  confirmations.Allow=true;recording=true;state.Invoke(state.Find("Button_ResetAlgoParams")!);recording=false;
  Check(service.Clears.SequenceEqual(new[]{"CalibPathName","RefreshFileEnable","WeightFactor"}),"only three source ISubInfo bindings are attempted in resource order: "+key);
  Check(applied.Count==9,"three user flags and six accepted default attempts, excluding rejected empty path: "+key);
  int manualWeight=applied[2]["WeightFactor"].GetInt32();
  Check(applied[3]["RefreshFileEnable"].GetBoolean()==false&&applied[3]["HomoFreedom"].GetInt32()==3&&applied[3]["WeightFun"].GetInt32()==1&&applied[3]["WeightFactor"].GetInt32()==manualWeight,"RefreshFileEnable is the first default write after authoritative binding readback: "+key);
  Check(applied[4]["Data1"].GetString()=="Data1#1"&&applied[5]["Data2"].GetString()=="Data2#1"&&applied[6]["HomoFreedom"].GetInt32()==1&&applied[7]["WeightFun"].GetInt32()==3&&applied[8]["WeightFactor"].GetInt32()==20,"source seven-item order continues after empty path and intermediate failure: "+key);
  Check(backing["CalibPathName"].GetString()==oldPath&&backing["Data3"].GetString()=="Data3#1"&&backing["Data8"].GetString()=="Data8#1"&&state.Find("Data3")!.CustomVisible&&state.Find("Data8")!.CustomVisible,"old local path and Data3 through Data8 visibility survive partial reset: "+key);
  Check(backing["WeightFactor"].GetInt32()==20&&backing["WeightFun"].GetInt32()==3&&backing["HomoFreedom"].GetInt32()==(rejectHomo?3:1),"later defaults apply even when intermediate host item fails: "+key);
  Check(state.Find("WeightFactor")!.Value==manualWeight.ToString()&&state.Find("HomoFreedom")!.Value=="3","failed reset does not perform full success readback: "+key);
  Check(state.Find("WeightFactor")!.SubscriptionBinding is null&&state.Find("WeightFactor")!.Get("IsSub")=="False"&&backing["WeightFactor"].GetInt32()==20,"unbinding follows authoritative readback and final default is twenty: "+key);
  Check(service.Bindings.ContainsKey("RefreshFileEnable")==rejectBinding&&state.Find("RefreshFileEnable")!.Get("IsSub")=="False","failed binding clear is retained while other clears/default writes continue: "+key);
  Check(atomic==0&&runs==0&&notifications.Items.All(n=>n.Kind!=ConfigurationNotificationKind.Success),"reset never invokes atomic service, execution or success notification: "+key);
  Check(notifications.Items.Last().Message.Contains(rejectHomo?"host rejected HomoFreedom":"0xe0000204"),"last failed default determines final error: "+key);
  if(!rejectHomo){string file=Path.Combine(output,key+"-after-reset.iwcal");plugin.SaveCalibration(context with{Node=node with{Parameters=backing}},file);Check(File.Exists(file),"partial reset preserves valid cache for explicit save: "+key);session.Dispose();string closed=Path.Combine(output,key+"-after-close.iwcal");plugin.SaveCalibration(context with{Node=node with{Parameters=backing}},closed);Check(File.ReadAllBytes(file).SequenceEqual(File.ReadAllBytes(closed)),"configuration close preserves the same execution-scope cache: "+key);scope.RemoveNode(CameraMappingPlugin.Id,"map");bool removed=false;try{plugin.SaveCalibration(context with{Node=node with{Parameters=backing}},Path.Combine(output,"removed.iwcal"));}catch(CameraMappingOperationException error){removed=error.NativeErrorCode==0xe0000018;}Check(removed,"node removal drops its calibration cache: "+key);rootScope.Dispose();using var reopened=new ModuleExecutionScope();bool isolated=false;try{plugin.SaveCalibration(context with{Scope=reopened.ForProcedure(key)},Path.Combine(output,"unexpected.iwcal"));}catch(CameraMappingOperationException error){isolated=error.NativeErrorCode==0xe0000018;}Check(isolated,"released solution scope does not share cache with reopened scope: "+key);}
 }
 sealed class Subscriptions:IToolConfigurationSubscriptionService {public readonly Dictionary<string,ConfigurationSubscriptionBinding> Bindings=[];public readonly List<string> Clears=[];public string? Reject;public void Seed(string name,string type,string value)=>Bindings[name]=new(new ConfigurationConstantReference(type,value),ConfigurationSubscriptionIndex.All);public ConfigurationSubscriptionTreeResult Enumerate(ConfigurationSubscriptionQuery query)=>new(ConfigurationSubscriptionStatus.Available,[]);public ConfigurationSubscriptionBindingResult Read(ConfigurationSubscriptionDestination destination)=>new(ConfigurationSubscriptionStatus.Available,Bindings.GetValueOrDefault(destination.Name),Bindings.TryGetValue(destination.Name,out var value)?((ConfigurationConstantReference)value.Reference).Literal:"");public ConfigurationSubscriptionBindingResult Bind(ConfigurationSubscriptionDestination destination,ConfigurationSubscriptionBinding? binding){if(binding is null){Clears.Add(destination.Name);if(destination.Name==Reject)return new(ConfigurationSubscriptionStatus.Failed,Bindings.GetValueOrDefault(destination.Name),Diagnostic:"host rejected clear");Bindings.Remove(destination.Name);}else Bindings[destination.Name]=binding;return Read(destination);}}
 sealed class Confirmations:IToolConfigurationConfirmationService {public bool Allow;public bool Confirm(Window? owner,ConfigurationConfirmation request)=>Allow;}
 sealed class Notifications:IToolConfigurationNotificationService {public readonly List<ConfigurationNotification> Items=[];public ConfigurationNotificationResult Notify(Window? owner,ConfigurationNotification value){Items.Add(value);return new(ConfigurationNotificationStatus.Displayed);}}
}
